                seikaku = (ushort)firstPokemon.GetSeikaku();
            }
        }

        var party = EncountTools.CreateSimpleParty(mons, level, MonsNo.NULL, 1, null, sex, seikaku, 0xFF, 0xFFFF, (ushort)formNo, 0, talentVNum);

        // @0179f85c: the member pointer is fetched before the tokusei3rd test.
        var enemy = party.GetMemberPointer(0);
        if (tokusei3rd)
            enemy.SetTokusei3rd();

