	private void AttributeEventEffect() {
        while (_attributeEntityEffect.Count > 0)
        {
            var attributeEvent = _attributeEntityEffect.Dequeue();
            if (!SmartPoint.AssetAssistant.UnityExtensions.GameObjectExtension.IsValid(attributeEvent.entity))
                return;

            // SHIPPED: the effect lookup passes debugdraw = true (@0179bde0), the SE lookup false.
            var attributeEx = GameManager.GetAttributeEx(attributeEvent.entity.gridPosition, attributeEvent.entity.worldPosition.y, true);
            if (attributeEx == null)
                return;

            EffectFieldID effectA;
            EffectFieldID effectB;
            if (attributeEvent.eventType == AttributeEventType.Jump)
            {
                effectA = attributeEx.EffectJumpSunnyA;
                effectB = attributeEx.EffectJumpSunnyB;
            }
            else if (attributeEvent.eventType == AttributeEventType.Run)
            {
                bool isSunny = WeatherWork.GetFieldSunny();
                if (attributeEvent.isBic)
                {
                    if (isSunny)
                    {
                        effectA = attributeEx.EffectBicycleSunnyA;
                        effectB = attributeEx.EffectBicycleSunnyB;
                    }
                    else
                    {
                        effectA = EffectFieldID.NONE;
                        effectB = EffectFieldID.NONE;
                        if (WeatherWork.GetFieldRain())
                        {
                            effectA = attributeEx.EffectBicycleRainA;
                            effectB = attributeEx.EffectBicycleRainB;
                        }
                    }
                }
                else if (attributeEvent.isRun)
                {
                    if (isSunny)
                    {
                        effectA = attributeEx.EffectRunSunnyA;
                        effectB = attributeEx.EffectRunSunnyB;
                    }
                    else
                    {
                        effectA = EffectFieldID.NONE;
                        effectB = EffectFieldID.NONE;
                        if (WeatherWork.GetFieldRain())
                        {
                            effectA = attributeEx.EffectRunRainA;
                            effectB = attributeEx.EffectRunRainB;
                        }
                    }
                }
                else
                {
                    if (isSunny)
                    {
                        effectA = attributeEx.EffectWalkSunnyA;
                        effectB = attributeEx.EffectWalkSunnyB;
                    }
                    else
                    {
                        effectA = EffectFieldID.NONE;
                        effectB = EffectFieldID.NONE;
                        if (WeatherWork.GetFieldRain())
                        {
                            effectA = attributeEx.EffectWalkRainA;
                            effectB = attributeEx.EffectWalkRainB;
                        }
                    }
                }
            }
            else
            {
                continue;
            }

            CallEffect(effectA, attributeEvent.entity.transform, null, null);
            CallEffect(effectB, attributeEvent.entity.transform, null, null);
        }
    }
	private void AttributeEventSE() {
        while (_attributeEntitySE.Count > 0)
        {
            var attributeEvent = _attributeEntitySE.Dequeue();
            var attributeEx = GameManager.GetAttributeEx(attributeEvent.entity.gridPosition, attributeEvent.entity.worldPosition.y, false);
            if (attributeEx == null)
                return;

            if (attributeEvent.eventType == AttributeEventType.Jump)
            {
                AudioManager.Instance.PlaySe(AK.EVENTS.S_FI005, null);
            }
            else if (attributeEvent.eventType == AttributeEventType.Run)
            {
                if (WeatherWork.GetFieldSunny())
                {
                    if (attributeEvent.isBic)
                        FootSE_Bic(PlayerWork.bicycleGear ? attributeEx.SoundLabelBicycleGear4Sunny : attributeEx.SoundLabelBicycleGear3Sunny);
                    else
                        FootSE_Walk(attributeEvent.isRun ? attributeEx.SoundLabelRunSunny : attributeEx.SoundLabelSunny, attributeEvent.callType,
                            attributeEvent.entity.EventParams.CharacterGraphicsIndex, attributeEvent.entity.transform);
                }
                else if (WeatherWork.GetFieldRain())
                {
                    if (attributeEvent.isBic)
                        FootSE_Bic(PlayerWork.bicycleGear ? attributeEx.SoundLabelBicycleGear4Rain : attributeEx.SoundLabelBicycleGear3Rain);
                    else
                        FootSE_Walk(attributeEvent.isRun ? attributeEx.SoundLabelRunRain : attributeEx.SoundLabelRain, attributeEvent.callType,
                            attributeEvent.entity.EventParams.CharacterGraphicsIndex, attributeEvent.entity.transform);
                }
            }
        }
    }
	private void FootSE_Walk(string name, global::FieldManager.AttributeEventCallType callType, int graphicIndex, global::UnityEngine.Transform tra) {
        if (string.IsNullOrEmpty(name))
            return;

        if (_WalkEventName_Attribute == 0)
            _WalkEventName_Attribute = AudioManager.Instance.GetIdByName("Attribute");

        uint switchId = AudioManager.Instance.GetIdByName(name);

        uint eventId;
        if (callType == AttributeEventCallType.Player)
            eventId = AK.EVENTS.PLAY_PLAYER;
        else if (graphicIndex == 18 || graphicIndex == 30)
            eventId = AK.EVENTS.PLAY_NPC_HEEL;
        else
            eventId = AK.EVENTS.PLAY_NPC;

        var se = AudioManager.Instance.CreateSe(eventId, 0, Vector3.zero, Quaternion.identity, tra);
        // SHIPPED: SetSwitch runs before the null test (@017a0038 then `cbz x20` @017a003c).
        se.SetSwitch(_WalkEventName_Attribute, switchId);
        if (se != null)
            se.Play(null, false);
    }
	private void FootSE_Bic(string name) {
        var se = AudioManager.Instance.CreateSe(AudioManager.Instance.GetIdByName(name), 0);
        if (se != null)
            se.Play(null, false);
    }
